const number=(value,digits=0)=>Number(value).toLocaleString('en',{maximumFractionDigits:digits});
const percent=value=>`${number(value*100,2)}%`;
export function summarizeGrid(grid){
 const rows=grid.rows.filter(row=>row.valid===row.runs&&row.runs>0);
 const orders=[...new Set(rows.map(row=>row.orders))].sort((a,b)=>a-b);
 const best=orders.map(order=>rows.filter(row=>row.orders===order).sort((a,b)=>a.mean_unfulfilled-b.mean_unfulfilled||a.mean_tardiness_minutes-b.mean_tardiness_minutes||a.mean_total_cost-b.mean_total_cost)[0]);
 return {rows,orders,best,runs:rows.reduce((sum,row)=>sum+row.runs,0),valid:rows.reduce((sum,row)=>sum+row.valid,0)};
}
export function summarizeTooling(report){
 return report.groups.map(group=>{
  const variants=['off','hard-all'].map(variant=>{
   const rows=group.rows.filter(row=>row.variant===variant);
   return {variant,runs:rows.length,valid:rows.length>0&&rows.every(row=>row.valid&&row.terminal),
    seeds:rows.map(row=>row.seed).sort((a,b)=>a-b),
    orders:rows.reduce((sum,row)=>sum+row.metrics.orders,0),
    shipped:rows.reduce((sum,row)=>sum+row.metrics.shipped,0),
    complete:rows.filter(row=>row.metrics.all_orders_fulfilled).length,
    relocations:rows.reduce((sum,row)=>sum+Object.values(row.tool_metrics.relocations).reduce((a,b)=>a+b,0),0)};
  });
  return {orders:group.orders,variants,valid:variants.every(row=>row.valid)&&JSON.stringify(variants[0].seeds)===JSON.stringify(variants[1].seeds)&&variants[0].orders===variants[1].orders};
 });
}
