const metrics={mean_unfulfilled:{name:'Orders left unshipped · lower is better',unit:'orders',explanation:'Average number of orders still unshipped at the 96-hour cutoff, including urgent arrivals. Zero means everything was shipped; it does not mean everything was on time.'},mean_tardiness_minutes:{name:'Deadline debt at cutoff · lower is better',unit:'minutes',explanation:'Delivered orders contribute their actual late minutes. Unshipped orders contribute debt only through the 96-hour cutoff; their eventual lateness is unknown. Add these terms, then average across runs. This cutoff-censored score is distinct from delivered-only tardiness.'},completion:{name:'Runs shipping every order · higher is better',unit:'fraction',explanation:'Fraction of checked runs in which every realized order was shipped by the 96-hour cutoff. Late deliveries still count as shipped. 100% here describes these training runs, not a guarantee on future scenarios.'}};
